sp_header_footer.client_script:
api.controller = function($scope) {
    /* BCE Global Tech header: switch to the team name as soon as the team registers */
    var c = this;

    // "Open ServiceNow Platform" appears when the crossword opens and hides once the team is done.
    $scope.$on('fun.gameState', function(e, state) {
        c.data.showPlatform = state == 'running';
    });

    $scope.$on('fun.teamRegistered', function(e, team) {
        if (!team || !team.name) return;
        c.data.displayName = team.name;
        var parts = team.name.trim().split(/\s+/);
        c.data.initials = parts.length > 1
            ? (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
            : parts[0].substring(0, 2).toUpperCase();
    });
};

sp_header_footer.css:
/* BCE Global Tech header for the Fun on PDI portal */
.bce-head {
  font-family: Arial, "Helvetica Neue", Helvetica, sans-serif;
  color: #fff;
}
.bce-bar {
  background: #00549a;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px #{unquote("max(16px, calc((100% - 1140px) / 2))")};
}
.bce-brand {
  display: flex;
  align-items: baseline;
  gap: 18px;
  color: #fff;
  text-decoration: none;
}
.bce-brand:hover,
.bce-brand:focus { color: #fff; text-decoration: none; }
/* The logo is blue and black, so it sits on a white chip to stay readable on the blue bar.
   If you upload a white (reversed) logo instead, delete the background and padding below. */
.bce-logo-chip {
      display: inline-flex;
      align-items: center;
      align-self: center;
}
.bce-logo-img {
  display: block;
  height: 65px;
  width: auto;
}
.bce-brand { align-items: center; }
.bce-logo {
  font-size: 28px;
  letter-spacing: -0.5px;
  font-weight: 300;
  line-height: 1;
  white-space: nowrap;
}
.bce-logo strong { font-weight: 800; }
.bce-app {
  font-size: 24px;
  font-weight: 300;
  padding-left: 18px;
  border-left: 1px solid rgba(255, 255, 255, 0.45);
  line-height: 1;
}
.bce-user {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 15px;
}
.bce-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #fff;
  color: #00549a;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.bce-logout {
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 16px;
  padding: 4px 12px;
  font-size: 13px;
}
.bce-logout:hover,
.bce-logout:focus { color: #00549a; background: #fff; text-decoration: none; }
.bce-sub {
  background: #003778;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 10px #{unquote("max(16px, calc((100% - 1140px) / 2))")};
  font-size: 14px;
}
.bce-event { font-weight: 700; }
.bce-app { white-space: nowrap; }
.bce-sub a { color: #fff; opacity: 0.85; }
.bce-sub a.is-current { opacity: 1; font-weight: 700; }
.bce-sub a.bce-platform {
  margin-left: auto;
  opacity: 1;
  font-weight: 700;
  padding: 3px 12px;
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 14px;
}
.bce-sub a.bce-platform:hover,
.bce-sub a.bce-platform:focus { background: #fff; color: #003778; text-decoration: none; }
.bce-sub a:focus-visible,
.bce-logout:focus-visible,
.bce-brand:focus-visible { outline: 2px solid #9fd0ff; outline-offset: 3px; }

@media (max-width: 640px) {
  .bce-logo { font-size: 22px; }
  .bce-logo-img { height: 26px; }
  .bce-app { font-size: 18px; padding-left: 12px; }
  .bce-name { display: none; }
}

sp_header_footer.script:
(function() {
    /* BCE Global Tech header: theme logo, signed-in team or user, current page */
    data.loggedIn = gs.isLoggedIn();

    // Same header on both portals: /fun (players) and /fun_gm (game masters).
    var portalRec = $sp.getPortalRecord();
    data.suffix = portalRec ? portalRec.getValue('url_suffix') : 'fun';
    var isGameMaster = data.suffix == 'fun_gm';
    data.home = isGameMaster ? 'fun_console' : 'crossword';
    data.section = 'Fun on Platform';
    data.nav = isGameMaster
        ? [{ id: 'fun_console', label: 'Console' }, { id: 'fun_leaderboard', label: 'Leaderboard' }]
        : [];
    // Players hunt for the words in the platform UI, opened in a new tab so the crossword stays open.
    // The link shows only while the game is running; the crossword widget updates it live.
    data.platformUrl = isGameMaster ? '' : '/now/nav/ui/home';
    data.showPlatform = false;
    if (!isGameMaster) {
        var pz = new GlideRecord('x_1802710_fun_on_0_puzzle');
        pz.addActiveQuery();
        pz.orderByDesc('sys_created_on');
        pz.setLimit(1);
        pz.query();
        data.showPlatform = pz.next() && pz.getValue('game_state') == 'running';
    }
    data.page = $sp.getParameter('id') || data.home;

    // Show the team name once the team has registered, otherwise the user name.
    data.displayName = gs.getUserDisplayName();
    var team = new GlideRecord('x_1802710_fun_on_0_team');
    team.addQuery('user', gs.getUserID());
    team.addActiveQuery();
    team.setLimit(1);
    team.query();
    if (team.next()) {
        var reg = String(team.getValue('registered'));
        if (reg == '1' || reg == 'true') data.displayName = team.getValue('name');
    }
    data.initials = initialsOf(data.displayName);

    // Logo: served from System UI > Images (db_image), which every signed-in user can read.
    // The theme's Logo field is only a fallback (its download link is checked against theme access).
    // Images created with the app selected get the scope prefix, so accept both names.
    var LOGO_NAMES = ['x_1802710_fun_on_0.bce_logo_white.png', 'bce_logo.png'];
    data.logoAlt = 'BCE Global Tech';
    data.logo = '';
    var img = new GlideRecord('db_image');
    img.addQuery('name', 'IN', LOGO_NAMES.join(','));
    img.orderByDesc('sys_updated_on');
    img.setLimit(1);
    img.query();
    if (img.next()) {
        data.logo = '/' + img.getValue('name');
    } else {
        var portal = $sp.getPortalRecord();
        if (portal) {
            var theme = portal.theme.getRefRecord();
            if (theme && theme.isValidRecord()) data.logo = imageUrl('sp_theme', theme.getUniqueValue(), 'logo');
        }
    }

    function imageUrl(table, sysId, field) {
        var att = new GlideRecord('sys_attachment');
        att.addQuery('table_name', 'ZZ_YY' + table);
        att.addQuery('table_sys_id', sysId);
        att.addQuery('file_name', field);
        att.orderByDesc('sys_created_on');
        att.setLimit(1);
        att.query();
        return att.next() ? '/sys_attachment.do?sys_id=' + att.getUniqueValue() : '';
    }

    function initialsOf(name) {
        var parts = String(name || '').replace(/^\s+|\s+$/g, '').split(/\s+/);
        if (parts.length > 1) return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
        return (parts[0] || '?').substring(0, 2).toUpperCase();
    }
})();
